function resourceTiles(q,perUnit=false,id=''){const v=perUnit?q.unitResources:q.resources;return `<div ${id?`id="${id}"`:''} class="resource-grid">${q.unlockedResources.map(k=>`<div class="resource-tile" data-resource="${k}" data-value="${v[k]}">${resourceArt(k)}<div class="resource-data"><span>${resourceNames[k]}</span><strong><bdi>${fmt(v[k])}</bdi></strong>${perUnit?'':`<small><bdi>${fmt(q.unitResources[k])}</bdi> للجندي الواحد</small>`}</div></div>`).join('')}</div>`;}
function powerTiles(q){const names={attack:'هجوم',defense:'دفاع ضد المشاة',cavalryDefense:'دفاع ضد الفرسان'},classes={attack:'attack',defense:'defense',cavalryDefense:'cavalry'};return `<div id="combatPerUnit" class="power-grid">${Object.keys(names).map(k=>`<div class="power-tile ${classes[k]}" data-stat="${k}" data-value="${q.combat.perUnit[k]}">${statArt(classes[k])}<strong><bdi>${powerFmt(q.combat.perUnit[k])}</bdi></strong><span>${names[k]}</span></div>`).join('')}</div><p class="power-total-label">القوة المجمّعة لـ <bdi>${fmt(q.count)}</bdi> ${q.building==='workshop'?'آلة':'جندي'}</p><div id="combatTotal" class="power-total">${Object.keys(names).map(k=>`<div data-stat="${k}" data-value="${q.combat.total[k]}"><b>${powerFmt(q.combat.total[k])}</b><span>${names[k]}</span></div>`).join('')}</div>`;}
function getInput(){const raw=$('trainCount').value.trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776));if(!/^\d+$/.test(raw))throw Error('أدخل عددًا صحيحًا من 1 إلى 1,000,000 وحدة.');return{building,unitId:$('unitSelect').value,count:Number(raw),forge:Number($('forgeLevel').value),buildingLevel:Number($('buildingLevel').value),castleLevel:Number($('castleLevel').value),heroPalaceLevel:Number($('heroPalaceLevel').value)};}
function unlockText(u){return u.unlock?`يتاح عند ${u.unlock.name} مستوى ${u.unlock.level}`:'وحدة الثكنة الأساسية';}
function fixedTraits(q,prefix=''){return `<div class="fixed-traits"><div><span>سرعة الحركة الثابتة</span><b id="${prefix}movementValue" data-value="${q.movementSpeed}">${fmt(q.movementSpeed)}</b></div><div><span>حمولة الوحدة الثابتة</span><b id="${prefix}cargoValue" data-value="${q.cargo}">${fmt(q.cargo)}</b></div></div><p class="fixed-note">لا يغيّرهما الحداد أو مستوى مبنى التدريب.</p>`;}
function timeBreakdown(q){return `<div class="time-breakdown"><div><span>المرجع السابق للوحدة</span><b data-time="reference" data-seconds="${q.referenceBaseSeconds}">${durationExact(q.referenceBaseSeconds)}</b></div><div class="time-base-cut"><span>الأساس الجديد بعد خصم ٧٠٪</span><b data-time="base" data-seconds="${q.baseSeconds}">${durationExact(q.baseSeconds)}</b></div><div><span>بعد تجهيز الحداد</span><b data-time="forge" data-seconds="${q.timeBeforeBuildingSeconds}">${durationExact(q.timeBeforeBuildingSeconds)}</b></div><div class="time-final"><span>بعد تخفيض المبنى</span><b data-time="final" data-seconds="${q.singleUnitSeconds}">${duration(q.singleUnitSeconds)}</b></div></div><p class="mini-note">الأساس والحداد بالزمن الدقيق. وقت الوحدة النهائي مقرب لأعلى إلى ثانية؛ مدة الدفعة تُحسب من الزمن الدقيق ثم تُقرب مرة واحدة.</p>`;}
function resourceReferenceTable(q){return `<table class="dialog-stats resource-reference"><thead><tr><th>المورد</th><th>أساس نسخة ٣</th><th>بعد +٧٠٪</th><th>مع الحداد</th></tr></thead><tbody>${RESOURCES.map(k=>`<tr data-reference-resource="${k}"><td>${resourceNames[k]}</td><td data-resource-stage="previous" data-value="${q.previousBaseUnitResources[k]}">${powerFmt(q.previousBaseUnitResources[k])}</td><td data-resource-stage="current" data-value="${q.baseUnitResources[k]}">${powerFmt(q.baseUnitResources[k])}</td><td data-resource-stage="final" data-value="${q.unitResources[k]}">${q.unlockedResources.includes(k)?fmt(q.unitResources[k]):'مغلق'}</td></tr>`).join('')}</tbody></table><p class="dialog-explain">الزيادة من أساس الموارد الدقيق للنسخة الثالثة، ثم تطبيق الحداد والتقريب مرة واحدة. أساس الموارد الحالي = مرجع النسخة الثانية ×٠٫٥١. لا يُطلب المورد المغلق، ولا يتغير الوقت بهذه الزيادة.</p>`;}
function renderBuilding(){const config=BUILDING_CONFIG[building];document.querySelectorAll('[data-building]').forEach(el=>{const yes=el.dataset.building===building;el.classList.toggle('active',yes);el.setAttribute('aria-pressed',String(yes));});$('setupTitle').textContent=config.name;$('campScene').innerHTML=campArt(building);$('buildingNote').textContent=building==='stable'?'ثلاثة فرسان. الفتح من قصر الأبطال ٣، ٧، ١٠. حد الدفعة يبدأ من ١٥٠، والموارد تتبع مستوى الإسطبل.':building==='workshop'?'ورشة العربات عند قلعة ١٠. الموارد +٧٠٪ من النسخة الثالثة، والوقت كما هو؛ حدها الأساسي ٧٥.':'ثلاث وحدات مشاة. القوة من صورك. الموارد +٧٠٪ من النسخة الثالثة، والوقت كما هو؛ حد الدفعة يبدأ من ٣٠٠.';$('unitSelect').innerHTML=config.unitIds.map(id=>`<option value="${id}">${unitMap[id].name}</option>`).join('');const s=stateByBuilding[building];$('unitSelect').value=s.unitId;$('buildingLevel').value=String(s.buildingLevel);$('forgeLevel').value=String(s.forge);$('trainCount').value=String(s.count);$('castleLevel').value=String(s.castleLevel??30);$('heroPalaceLevel').value=String(s.heroPalaceLevel??30);renderUnit();calculate();}
function renderUnit(){selectedUnit=$('unitSelect').value;const u=unitMap[selectedUnit];$('unitName').textContent=u.name;$('unitCategory').textContent=u.category;$('unitRole').textContent=u.role;$('selectedUnitArt').innerHTML=unitArt(u.id);$('unitRoster').innerHTML=BUILDING_CONFIG[building].unitIds.map(id=>`<button type="button" class="unit-choice ${id===u.id?'active':''}" data-unit="${id}" aria-label="اختيار ${esc(unitMap[id].name)}" aria-pressed="${id===u.id}">${unitArt(id)}<span>${esc(unitMap[id].short)}</span></button>`).join('');}
function renderAvailability(q){const a=q.availability;const requirements=a.requirements||[];$('unlockSummary').textContent=a.available?'متاحة':'معاينة فقط';$('unlockSummary').className=a.available?'available-label':'locked-label';$('unlockStatus').innerHTML=requirements.length?requirements.map(r=>`<div class="unlock-requirement ${r.met?'met':'unmet'}"><span>${r.met?'✓':'!'} ${esc(r.name)} مستوى ${r.required}</span><b>الحالي ${r.current}</b></div>`).join(''):'<p class="mini-note">لا يوجد شرط فتح إضافي لهذه الوحدة في قواعد المحاكي.</p>';}
function renderQuote(q){const u=unitMap[q.unitId];const d=buildingTimeDetails(q.buildingLevel);const eraSentence=q.buildingLevel<5?'قمح وخشب فقط. يضاف الطين عند ٥ والحديد عند ١٠.':q.buildingLevel<10?'الطين مضاف إلى التكلفة. الحديد يبدأ عند ١٠.':'الموارد الأربعة مطلوبة في هذا المستوى.';
$('quotePanel').innerHTML=`<div class="quote-heading"><div><small>ملخص طلب التدريب</small><h2><bdi>${fmt(q.count)}</bdi> ${esc(q.name)}</h2><p>${esc(q.buildingName)} مستوى <bdi>${q.buildingLevel}</bdi> · ${q.forge===0?'بدون حداد':`حداد <bdi>${q.forge}</bdi>`}</p></div><button class="quote-number art-button" type="button" data-open-unit aria-label="فتح بطاقة الجندي">${unitArt(u.id)}</button></div>${!q.availability.available?`<div id="availabilityNotice" class="availability-notice"><b>معاينة تكلفة — الوحدة مغلقة</b><p>${q.availability.reasons.map(esc).join(' · ')}</p></div>`:''}<section class="quote-section"><div class="subheading"><h3>قوة الجندي الواحد</h3><span class="forge-chip">الحداد +<bdi>${pct(q.forgeBonusPercent)}</bdi></span></div>${powerTiles(q)}${fixedTraits(q)}<p class="source-note">${u.proposal?'الحصار: قوة الاشتباك محفوظة؛ مرجع الموارد ×٠٫٥١ ومرجع الوقت ×٠٫٣٠.':'القوة من جداول الصور؛ الموارد +٧٠٪ من النسخة الثالثة. أساس الوقت بلا تغيير.'}</p></section><section class="quote-section"><div class="subheading"><h3>الموارد المطلوبة للكمية</h3><small>${q.unlockedResources.length} أنواع موارد</small></div>${resourceTiles(q,false,'resourceCosts')}<p class="era-note">${eraSentence} الإجمالي: <bdi>${fmt(q.resourceTotal)}</bdi>. أساس النسخة الثالثة ×١٫٧٠، ثم الحداد وتقريب المورد لأعلى مرة واحدة للوحدة. لا يعاد توزيع المورد المغلق.</p></section><section class="quote-section"><div class="subheading"><h3>تخفيض وقت المبنى</h3><span id="reductionValue" class="reduction-chip" data-value="${q.trainingReductionPercent}">−${pct(q.trainingReductionPercent)} من المدة</span></div><div class="combined-reduction"><span>خصم الأساس ٧٠٪ ثم تخفيض المبنى</span><b id="totalReductionValue" data-value="${q.totalTimeReductionVsReferencePercent}">${pct(q.totalTimeReductionVsReferencePercent)} إجماليًا</b><small>مقارنة بزمن النسخة السابقة، عند الحداد نفسه وقبل تقريب الثواني.</small></div>${timeBreakdown(q)}<div class="cost-highlight"><div class="time-cost"><span class="cost-icon">${simpleArt('time')} وقت تدريب الكمية</span><strong id="timeValue" data-seconds="${q.seconds}">${duration(q.seconds)}</strong><small>للوحدة منفردة: ${duration(q.singleUnitSeconds)}</small></div><div class="gold-cost"><span class="cost-icon">${simpleArt('gold')} إنهاء اختياري بالذهب</span><strong id="goldValue" data-value="${q.totalGold}">${fmt(q.totalGold)}</strong><small>مع دفع الموارد المطلوبة</small></div></div><div class="gold-explain"><span>متوسط الوحدة: <bdi>${fmt(q.averageGold)}</bdi> ذهب</span><span>توفير الدفعات: <bdi>${fmt(q.goldSaved)}</bdi> ذهب</span><span>خصم فعلي: <bdi>${pct(q.effectiveDiscountPercent)}</bdi></span></div><p class="free-line">✓ التدريب بالانتظار: <bdi>${q.normalGold}</bdi> ذهب</p><p class="mini-note">الذهب تقدير وفق معامل ٩٦ ثانية لكل ذهب قبل الخصم.</p></section><section class="quote-section"><details class="batch-details" ${q.batches>1?'open':''}><summary><span>${q.batches>1?'الطلب مقسّم إلى دفعات':'تفاصيل دفعة التدريب'}</span><small><bdi id="batchCount" data-value="${q.batches}">${fmt(q.batches)}</bdi> ${q.batches===1?'دفعة':'دفعات'}</small></summary><div class="batch-list">${q.batchPlan.map(b=>`<div class="batch-row"><b>${b.repeats>1?`<bdi>${fmt(b.repeats)}</bdi> دفعات × `:''}<bdi>${fmt(b.count)}</bdi> ${q.building==='workshop'?'آلة':'جندي'}</b><span class="batch-number">${b.repeats>1?'لكل دفعة':'هذه الدفعة'}</span><div class="batch-meta"><span>${duration(b.seconds)}</span><span><bdi>${fmt(b.gold)}</bdi> ذهب اختياري</span></div></div>`).join('')}</div><p class="mini-note">${q.batches>1?'الإجمالي يتجاوز حد الطلب الواحد؛ التنفيذ دفعات متتالية. خصم كل دفعة مستقل.':'الكمية ضمن حد دفعة واحدة.'} المدة تفترض طابورًا فارغًا.</p></details></section>`;
$('forgeBonusLabel').textContent=q.forge===0?'القوة الأساسية دون تطوير':'مكافأة القوة +'+pct(q.forgeBonusPercent);$('buildingTimeSummary').innerHTML=`<div><small>تخفيض وقت المبنى</small><b>${pct(d.reductionPercent)}</b></div><div><small>${q.buildingLevel===30?'وصل الحد الأقصى':'المستوى التالي'}</small><b>${q.buildingLevel===30?'٨٠٪':pct(d.nextReductionPercent)}</b></div><p>${q.buildingLevel===30?'بعد خصم الأساس والمبنى تبقى ٦٪ من زمن المرجع عند الحداد نفسه.':`الترقية التالية تضيف ${fmt(d.nextIncrementPercentagePoints)} نقطة مئوية. الإجمالي من المرجع الآن ${pct(q.totalTimeReductionVsReferencePercent)}.`}</p>`;
$('capacitySummary').innerHTML=`<div class="capacity-values"><div><span>المستوى ${q.buildingLevel}</span><b><bdi id="capacityValue" data-value="${q.capacity}">${fmt(q.capacity)}</bdi></b><small>وحدة لكل طلب</small></div><div><span>${q.buildingLevel<30?'المستوى التالي '+(q.buildingLevel+1):'أعلى مستوى'}</span><b><bdi id="nextCapacityValue" data-value="${q.buildingLevel<30?capacity(q.building,q.buildingLevel+1):q.capacity}">${fmt(q.buildingLevel<30?capacity(q.building,q.buildingLevel+1):q.capacity)}</bdi></b><small>${q.buildingLevel<30?'نمو الحد ×١٫٢٥':'لا يوجد مستوى تالٍ'}</small></div></div><div class="capacity-bar"><i style="width:${Math.min(100,100*q.count/q.capacity)}%"></i></div><p id="batchNotice" data-batches="${q.batches}" class="batch-plan-notice ${q.batches>1?'multi':''}">${q.batches>1?`إجمالي التخطيط ${fmt(q.count)} يتجاوز الحد ${fmt(q.capacity)}. يُقسّم إلى ${fmt(q.batches)} دفعات متتالية؛ ليس طلبًا واحدًا مسموحًا.`:`${fmt(q.count)} من ${fmt(q.capacity)}: الكمية ضمن حد طلب واحد.`}</p>`;renderAvailability(q);document.querySelectorAll('.era-track [data-level]').forEach(el=>{const x=Number(el.dataset.level);el.classList.toggle('active',x===4?q.buildingLevel<5:x===5?q.buildingLevel>=5&&q.buildingLevel<10:q.buildingLevel>=10);});}
function renderLevels(){if(!currentQuote){$('levelsGrid').innerHTML='';$('levelsContext').textContent='أدخل طلبًا صالحًا أولًا.';return;}const axis=$('levelsAxis').value,q=currentQuote;const rows=levelRows({...currentInput,axis});$('levelsContext').textContent=axis==='building'?`${q.name} · العدد ${fmt(q.count)} · حداد ${q.forge} ثابت. تتغير مرحلة الموارد والوقت والسعة.`:`${q.name} · العدد ${fmt(q.count)} · ${q.buildingName} مستوى ${q.buildingLevel} ثابت. الصف ٠ أساس بدون تطوير، ثم ١–٣٠.`;
$('levelsGrid').innerHTML=rows.map(r=>`<details class="level-row ${r.level===(axis==='building'?q.buildingLevel:q.forge)?'current-level':''}" data-level="${r.level}"><summary><span><bdi class="level-tag">${r.level}</bdi><span class="level-mini">${r.level===0?'الأساس':axis==='building'?'المبنى':'الحداد'}</span></span><span class="row-total" title="${fmt(r.resourceTotal)}">${compact(r.resourceTotal)}</span><span class="row-gold" title="${fmt(r.totalGold)}">${compact(r.totalGold)}</span></summary><div class="level-row-body">${resourceTiles(r)}<div class="row-facts"><span>وقت الكمية<b>${duration(r.seconds)}</b></span><span>وقت الوحدة<b>${duration(r.singleUnitSeconds)}</b></span><span>حد الدفعة<b>${fmt(r.capacity)}</b></span><span>عدد الدفعات<b>${fmt(r.batches)}</b></span><span>تخفيض المبنى<b>${pct(r.trainingReductionPercent)}</b></span><span>مكافأة الحداد<b>+${pct(r.forgeBonusPercent)}</b></span></div><div class="row-power"><span>هجوم الوحدة <b>${powerFmt(r.combat.perUnit.attack)}</b></span><span>دفاع المشاة <b>${powerFmt(r.combat.perUnit.defense)}</b></span><span>دفاع الفرسان <b>${powerFmt(r.combat.perUnit.cavalryDefense)}</b></span></div><p class="fixed-note">الحركة ${fmt(r.movementSpeed)} · حمولة الوحدة ${fmt(r.cargo)} — ثابتتان</p></div></details>`).join('');}
function calculate(){try{const input=getInput(),q=quoteTraining(input);currentQuote=q;currentInput=input;stateByBuilding[building]={...input};$('trainingError').hidden=true;for(const id of ['shareTraining','downloadQuote','unitDetails','buildingDetails','selectedUnitArt'])$(id).disabled=false;renderQuote(q);renderLevels();return q;}catch(e){currentQuote=null;currentInput=null;$('trainingError').textContent=e.message;$('trainingError').hidden=false;$('quotePanel').innerHTML='<div class="empty-quote"><strong>صحّح بيانات الطلب</strong><p>تظهر القوة والتكلفة بعد إدخال عدد ومستويات صالحة.</p></div>';for(const id of ['shareTraining','downloadQuote','unitDetails','buildingDetails','selectedUnitArt'])$(id).disabled=true;$('capacitySummary').innerHTML='';$('buildingTimeSummary').innerHTML='';$('unlockStatus').innerHTML='';$('unlockSummary').textContent='';renderLevels();return null;}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').hidden=true;},2200);}
function showDetails(){const q=currentQuote;if(!q)return;const u=unitMap[q.unitId];$('unitDialogTitle').textContent=u.name;$('unitDialogContent').innerHTML=`<div class="dialog-unit-art">${unitArt(u.id)}</div><p class="dialog-meta">${esc(u.category)} · ${q.forge===0?'بدون حداد':`حداد ${q.forge}`} · زيادة القوة +<bdi>${pct(q.forgeBonusPercent)}</bdi></p><p class="unlock-badge">${esc(unlockText(u))}</p><table class="dialog-stats"><thead><tr><th>القوة</th><th>الأساس</th><th>بعد الحداد</th></tr></thead><tbody><tr><td>الهجوم</td><td>${fmt(u.attack)}</td><td>${powerFmt(q.combat.perUnit.attack)}</td></tr><tr><td>دفاع ضد المشاة</td><td>${fmt(u.def)}</td><td>${powerFmt(q.combat.perUnit.defense)}</td></tr><tr><td>دفاع ضد الفرسان</td><td>${fmt(u.cavDef)}</td><td>${powerFmt(q.combat.perUnit.cavalryDefense)}</td></tr></tbody></table>${fixedTraits(q,'dialog-')}<p class="dialog-explain">${esc(u.role)}. قيمة كل خاصية للمجموعة = خاصية الوحدة × العدد. لا تجمع خصائص الهجوم والدفاع في رقم قوة واحد.</p><h3 class="dialog-section-title">موارد تجهيز وحدة واحدة</h3>${resourceTiles(q,true)}${resourceReferenceTable(q)}<h3 class="dialog-section-title">وقت تجهيز وحدة واحدة</h3>${timeBreakdown(q)}<p class="dialog-explain">موارد الحداد ×<bdi>${fmt(q.resourceFactor)}</bdi>، وجهده ×<bdi>${fmt(q.effortFactor)}</bdi>. ${esc(q.buildingName)} يخفض المدة <bdi>${pct(q.trainingReductionPercent)}</bdi>.</p><p class="source-note">${u.proposal?'الحصار: مرجع الموارد ×٠٫٥١ ومرجع الوقت ×٠٫٣٠؛ قوة الاشتباك محفوظة.':'القوة من جداولك. الوقت: مرجع النسخة الثانية ×٠٫٣٠، والموارد ×٠٫٥١، ثم أثر الحداد.'}</p>`;$('unitDialog').showModal();}
function showBuildingDetails(){const q=currentQuote;if(!q)return;const d=buildingTimeDetails(q.buildingLevel);$('buildingDialogTitle').textContent=q.buildingName;$('buildingDialogContent').innerHTML=`<div class="building-modal-art">${buildingArt(q.building)}</div><p class="dialog-meta">${esc(q.name)} · ${q.forge===0?'بدون حداد':`حداد ${q.forge}`} · الوقت أدناه لوحدة واحدة</p><div class="building-time-summary"><div><small>تخفيض المبنى من الوقت الجديد</small><b>${pct(d.reductionPercent)}</b></div><div><small>التخفيض الكلي من المرجع</small><b>${pct(q.totalTimeReductionVsReferencePercent)}</b></div><p>${q.buildingLevel<30?`المستوى التالي: ${pct(d.nextReductionPercent)}، بزيادة ${fmt(d.nextIncrementPercentagePoints)} نقطة مئوية.`:'المستوى ٣٠: تخفيض المبنى ٨٠٪، والإجمالي مع خصم الأساس ٩٤٪.'}</p></div><div class="modal-capacity"><span>حد الطلب الحالي</span><b>${fmt(q.capacity)}</b><span>المستوى التالي</span><b>${q.buildingLevel<30?fmt(capacity(q.building,q.buildingLevel+1)):'الحد الأقصى'}</b></div><p class="mini-note">نمو حد الدفعة ×١٫٢٥ لكل مستوى، مع حذف الكسر. التجاوز يُقسّم إلى دفعات متتالية.</p>${timeBreakdown(q)}<p class="dialog-explain">يبقى منحنى الوقت السابق بتأثير أكبر للمستويات العليا. يُطبق على الوقت الجديد بعد خصم الأساس ٧٠٪ وأثر الحداد؛ عند مستوى ٣٠ يبقى ٦٪ من وقت المرجع عند الحداد نفسه.</p><div class="building-level-head"><span>المستوى</span><span>تخفيض المبنى</span><span>مدة الوحدة</span><span>حد الدفعة</span></div><div id="buildingTimeRows">${Array.from({length:30},(_,i)=>{const level=i+1,r=quoteTraining({...currentInput,count:1,buildingLevel:level}),t=buildingTimeDetails(level);return `<div class="building-time-row ${level===q.buildingLevel?'current':''}" data-building-level="${level}"><b>${level}</b><span><strong>${pct(t.reductionPercent)}</strong><small>كلي ${pct(r.totalTimeReductionVsReferencePercent)}</small></span><b data-seconds="${r.singleUnitSeconds}">${duration(r.singleUnitSeconds)}</b><b data-capacity="${r.capacity}">${fmt(r.capacity)}</b></div>`;}).join('')}</div><p class="mini-note">الكلي = خصم الأساس ٧٠٪ ثم تخفيض المبنى من الوقت المتبقي، قبل تقريب المدة. أوقات الوحدات مقربة لأعلى إلى ثانية.</p>`;$('buildingDialog').showModal();}
function setSectionActive(section){for(const [key,id] of [['training','openTraining'],['forge','openForge'],['wall','openWall']]){const active=key===section;$(id).classList.toggle('active',active);$(id).setAttribute('aria-pressed',String(active));}}
function forgePreview(){const u=unitMap[$('forgeUnitSelect').value],stored=stateByBuilding[u.building];return quoteTraining({...stored,building:u.building,unitId:u.id,forge:Number($('forgeDetailLevel').value),count:1});}
function renderForgeDetails(){const q=forgePreview(),u=unitMap[q.unitId],next=q.forge<30?quoteTraining({...q,count:1,forge:q.forge+1}):null;const stats=[['الهجوم','attack',u.attack],['دفاع المشاة','defense',u.def],['دفاع الفرسان','cavalryDefense',u.cavDef]];
$('forgeDialogContent').innerHTML=`<div class="forge-unit-summary"><div class="forge-art">${unitArt(u.id)}</div><div><h3>${esc(u.name)}</h3><p>${esc(u.category)}</p><b class="forge-chip" id="forgePowerBonus" data-value="${q.forgeBonusPercent}">قوة +${pct(q.forgeBonusPercent)}</b></div></div><p class="dialog-explain">${esc(u.role)}. كل مستوى يضيف ٥٪ من قوة الأساس إلى الهجوم ودفاع المشاة ودفاع الفرسان.</p><table class="dialog-stats forge-stat-table"><thead><tr><th>الخاصية</th><th>بدون حداد</th><th>المستوى ${q.forge}</th><th>${next?'المستوى '+next.forge:'أعلى مستوى'}</th></tr></thead><tbody>${stats.map(([name,key,base])=>`<tr><td>${name}</td><td>${powerFmt(base)}</td><td data-forge-stat="${key}" data-value="${q.combat.perUnit[key]}">${powerFmt(q.combat.perUnit[key])}</td><td>${next?powerFmt(next.combat.perUnit[key]):'—'}</td></tr>`).join('')}</tbody></table><div class="forge-factors"><div><span>معامل القوة</span><b>×${fmt(q.forgeFactor)}</b><small>١ + ٠٫٠٥ × المستوى</small></div><div><span>معامل الموارد</span><b>×${fmt(q.resourceFactor)}</b><small>١ + ٠٫٠٦ × المستوى</small></div><div><span>معامل جهد التدريب</span><b>×${fmt(q.effortFactor)}</b><small>١ + ٠٫٠٤ × المستوى</small></div></div><h3 class="dialog-section-title">تجهيز جندي واحد بهذا الحداد</h3><p class="dialog-explain">${esc(q.buildingName)} مستوى ${q.buildingLevel} يحدد الموارد المتاحة وتخفيض الوقت. هذه تكلفة تدريب الجندي، وليست تكلفة ترقية مبنى الحداد.</p>${resourceTiles(q,true)}<div class="forge-training-result"><span>زمن تدريب الوحدة<strong id="forgeUnitSeconds" data-seconds="${q.singleUnitSeconds}">${duration(q.singleUnitSeconds)}</strong></span><span>إنهاء اختياري بالذهب<strong>${fmt(q.totalGold)}</strong></span></div><p class="mini-note">التدريب بالانتظار صفر ذهب، وتُدفع الموارد في الحالتين. زيادة تجهيز الموارد ٦٪ وجهد التدريب ٤٪ لكل مستوى من مقترح الموازنة المحفوظ.</p>${fixedTraits(q,'forge-')}<details class="forge-resource-details"><summary>حسبة الموارد والوقت بالتفصيل</summary>${resourceReferenceTable(q)}${timeBreakdown(q)}</details>`;}
function showForge(){const q=currentQuote;const fallback=stateByBuilding[building];$('forgeUnitSelect').value=q?.unitId??fallback.unitId;$('forgeDetailLevel').value=String(q?.forge??fallback.forge);renderForgeDetails();setSectionActive('forge');$('forgeDialog').showModal();}
const wallFieldMap={level:'wallLevel',hp:'wallHp',defenderUnitId:'wallDefenderUnit',defenderCount:'wallDefenderCount',defenderForge:'wallDefenderForge',arrivingRams:'wallArrivingRams',survivingRams:'wallSurvivingRams',ramForge:'wallRamForge',survivingCatapults:'wallSurvivingCatapults',catapultForge:'wallCatapultForge',usedDirect:'wallUsedDirect',usedHour:'wallUsedHour'};
function numericField(id){const raw=$(id).value.trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776));if(!/^\d+$/.test(raw))throw Error('أدخل عددًا صحيحًا غير سالب في '+($(id).getAttribute('aria-label')||'الحقل')+'.');return Number(raw);}
function getWallInput(){return Object.fromEntries([...Object.entries(wallFieldMap).map(([key,id])=>[key,key==='defenderUnitId'?$(id).value:numericField(id)]),['attackerWon',$('wallAttackerWon').checked]]);}
function wallStatTotals(q){const names={attack:'الهجوم ثابت',defense:'دفاع المشاة',cavalryDefense:'دفاع الفرسان'};return `<div class="wall-strength-totals">${Object.entries(names).map(([key,name])=>`<div><span>${name}</span><small>قبل السور ${powerFmt(q.defender.total[key])}</small><b data-wall-stat="${key}" data-value="${q.defender.fortifiedTotal[key]}">${powerFmt(q.defender.fortifiedTotal[key])}</b><small>بعد السور</small></div>`).join('')}</div>`;}
function renderWallQuote(q){const w=q.wall,d=q.defender;const stats=[['الهجوم','attack'],['دفاع المشاة','defense'],['دفاع الفرسان','cavalryDefense']];
$('wallResult').innerHTML=`<div class="wall-heading"><div class="wall-art">${buildingArt('barracks')}</div><div><small>السور مستوى ${w.level}</small><h3>دفاع القلعة</h3><p>${esc(d.name)} · ${fmt(d.count)} وحدة · حداد ${d.forge}</p></div></div><div class="wall-main-metrics"><div><span>المتانة الحالية / القصوى</span><b id="wallIntegrity" data-hp="${w.hp}" data-max="${w.max}">${fmt(w.hp)} <small>/ ${fmt(w.max)}</small></b><div class="wall-integrity-track"><i style="width:${w.max?100*w.hp/w.max:0}%"></i></div></div><div><span>مكافأة الدفاع الفعلية</span><b id="wallAppliedBonus" data-value="${w.appliedPercent}">+${pct(w.appliedPercent)}</b><small>تضاف إلى دفاع الجنود بعد الحداد</small></div></div><div class="wall-bonus-chain"><span>مكافأة المستوى <b>${pct(w.nominalPercent)}</b></span><span>سلامة السور <b>${pct(w.intactPercent)}</b></span><span>المكافأة مع المتانة <b>${pct(w.availablePercent)}</b></span><span>خفض المكافأة بالأكباش <b id="wallSuppression" data-value="${w.suppressionPercent}">${pct(w.suppressionPercent)}</b></span></div><p class="dialog-explain">كل مستوى سور يمنح ١٪ عند المتانة الكاملة. تقل المكافأة مع المتانة، ثم قد تخفضها الأكباش الواصلة حتى ٥٠٪. السور يقوّي الدفاع ضد المشاة والفرسان؛ الهجوم لا يتغير.</p><h3 class="dialog-section-title">قوة المدافعين الإجمالية</h3>${wallStatTotals(q)}<details class="wall-options wall-unit-details"><summary>تفاصيل قوة الجندي الواحد</summary><div class="wall-options-body"><table class="dialog-stats"><thead><tr><th>الخاصية</th><th>الأساس</th><th>بعد الحداد</th><th>مع السور</th></tr></thead><tbody>${stats.map(([name,key])=>`<tr><td>${name}</td><td>${powerFmt(d.base[key])}</td><td>${powerFmt(d.perUnit[key])}</td><td>${powerFmt(d.fortifiedPerUnit[key])}</td></tr>`).join('')}</tbody></table><p class="mini-note">القوة من قائمة الجنود الحالية، والحداد ${d.forge===0?'بدون تطوير':`+${pct(d.forgeBonusPercent)}`}. المتانة القصوى = مستوى السور ×١٬٠٠٠.</p></div></details><h3 class="dialog-section-title">نتيجة الضرر وفق مدخلاتك</h3><p class="mini-note">تعزيز الدفاع أعلاه حسب متانة بداية الهجمة؛ الضرر أدناه يحسب المتانة بعدها.</p><p class="wall-result-condition">${q.input.attackerWon?'المهاجم فائز حسب اختيارك؛ يُحسب ضرر آلاته الناجية ضمن الحدود.':'لم تُدخل فوز المهاجم؛ لا يُطبّق ضرر آلات ناجية على المتانة.'}</p><div class="wall-damage-grid"><div><span>ضرر مباشر قبل الحدود</span><b id="wallRawDamage" data-value="${w.directRaw}">${fmt(w.directRaw)}</b></div><div class="damage-emphasis"><span>الضرر المباشر المحتسب</span><b id="wallDirectDamage" data-value="${w.direct}">${fmt(w.direct)}</b></div><div><span>ضرر منعته الحدود</span><b id="wallPreventedDamage" data-value="${w.prevented}">${fmt(w.prevented)}</b></div><div><span>المتانة بعد المباشر</span><b id="wallHpAfter" data-value="${w.hpAfter}">${fmt(w.hpAfter)}</b></div><div><span>ضرر حريق محتمل خلال ٣٠ دقيقة</span><b id="wallFirePotential" data-value="${w.firePotential}">${fmt(w.firePotential)}</b></div><div><span>المتانة بعد الحريق المحتمل</span><b id="wallHpAfterFire" data-value="${w.hpAfterFire}">${fmt(w.hpAfterFire)}</b></div></div><p class="mini-note">الحريق تقدير مشروط ضمن مقترح الحصار، وليس مؤقتًا يعمل هنا. إدخال نتيجة فوز لا يجعل المحاكي يحسب المعركة أو يكشف جيشًا مخفيًا.</p><details class="wall-options"><summary>معادلات الحصار وحدود الضرر</summary><div class="wall-options-body"><p class="dialog-explain">الكبش الناجي: ١٢ نقطة ضرر أساسية، والمنجنيق الناجي: ٦ نقاط، مع أثر حداد الآلة. لا يكفي وصول الآلة وحده لإحداث ضرر مباشر؛ يلزم فوز المهاجم وبقاء الآلة.</p><div class="wall-bonus-chain"><span>حد المباشر خلال ٦٠ ثانية <b>${fmt(w.directCap)}</b></span><span>المستهلك منه <b>${fmt(w.usedDirect)}</b></span><span>حد الضرر خلال ساعة <b>${fmt(w.hourCap)}</b></span><span>المستهلك خلال الساعة <b>${fmt(w.usedHour)}</b></span><span>المتاح من حد الدقيقة <b>${fmt(w.remainingDirectBudget)}</b></span><span>المتاح من حد الساعة <b>${fmt(w.remainingHourBudget)}</b></span></div><p class="dialog-explain">حد المباشر ١٠٪ من المتانة القصوى خلال ٦٠ ثانية، وحد الساعة ٢٥٪. الضرر السابق يقلّل المتاح للهجمة الحالية. خفض المكافأة بالأكباش منفصل عن خصم نقاط المتانة.</p><p class="source-note">مكافأة ١٪ لكل مستوى والمتانة ١٬٠٠٠ لكل مستوى من قواعد السور المعتمدة. ضرر آلات الحصار والحريق وحدود الحماية من مقترح الموازنة المحفوظ؛ لا تمثل اختبارًا على خادم اللعبة.</p></div></details>`;}
function calculateWall(){try{const q=quoteWall(getWallInput());currentWallQuote=q;wallInitialized=true;$('wallError').hidden=true;$('wallHpLimit').textContent='الحد الأقصى '+fmt(q.wall.max);renderWallQuote(q);$('shareWall').disabled=false;$('downloadWall').disabled=false;return q;}catch(e){currentWallQuote=null;$('wallError').textContent=e.message;$('wallError').hidden=false;$('wallResult').innerHTML='';$('shareWall').disabled=true;$('downloadWall').disabled=true;return null;}}
function applyWallInput(input){const q=quoteWall(input);for(const[key,id]of Object.entries(wallFieldMap))$(id).value=String(q.input[key]);$('wallAttackerWon').checked=q.input.attackerWon;return calculateWall();}
function showWall(){if(!wallInitialized){const q=currentQuote??quoteTraining(stateByBuilding[building]);applyWallInput({level:10,hp:10000,defenderUnitId:q.unitId,defenderCount:q.count,defenderForge:q.forge,arrivingRams:0,survivingRams:0,ramForge:0,survivingCatapults:0,catapultForge:0,attackerWon:false,usedDirect:0,usedHour:0});}else calculateWall();setSectionActive('wall');$('wallDialog').showModal();}
async function exposeShare(url,id){$(id).value=url;$(id).hidden=false;try{await navigator.clipboard.writeText(url);toast('نُسخ رابط الحسبة');}catch{$(id).focus();$(id).select();toast('الرابط جاهز للنسخ');}}
function encodeWall(input){const normalized=quoteWall(input).input;return btoa(JSON.stringify({version:TRAINING_VERSION,input:normalized})).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function decodeWall(token){if(token.length>6000||!/^[A-Za-z0-9_-]+$/.test(token))throw Error('رابط السور غير صالح.');let value;try{value=JSON.parse(atob(token.replace(/-/g,'+').replace(/_/g,'/')));}catch{throw Error('رابط السور غير صالح.');}if(!value||value.version!==TRAINING_VERSION||!value.input||typeof value.input!=='object'||Array.isArray(value.input))throw Error('رابط السور من إصدار مختلف أو غير صالح.');return quoteWall(value.input).input;}
function applyInput(input){building=input.building;stateByBuilding[building]={...input,castleLevel:input.castleLevel??30,heroPalaceLevel:input.heroPalaceLevel??30};renderBuilding();}
for(const id of ['buildingLevel','castleLevel','heroPalaceLevel'])$(id).innerHTML=Array.from({length:30},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');
$('forgeLevel').innerHTML='<option value="0">٠ — بدون تطوير</option>'+Array.from({length:30},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');
document.querySelectorAll('[data-building-icon]').forEach(el=>{el.innerHTML=buildingArt(el.dataset.buildingIcon);});
document.querySelectorAll('[data-building]').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.building===building)return;building=el.dataset.building;renderBuilding();}));
$('unitSelect').addEventListener('change',()=>{renderUnit();calculate();});$('unitRoster').addEventListener('click',e=>{const b=e.target.closest('[data-unit]');if(!b)return;$('unitSelect').value=b.dataset.unit;renderUnit();calculate();});
for(const id of ['buildingLevel','forgeLevel','castleLevel','heroPalaceLevel'])$(id).addEventListener('change',calculate);$('trainCount').addEventListener('input',calculate);$('calculateTraining').addEventListener('click',()=>{if(calculate())toast('تم تحديث القوة والتكلفة والوقت');});
document.querySelectorAll('[data-count]').forEach(el=>el.addEventListener('click',()=>{$('trainCount').value=el.dataset.count;calculate();}));document.querySelectorAll('.era-track [data-level]').forEach(el=>el.addEventListener('click',()=>{$('buildingLevel').value=el.dataset.level;calculate();}));
$('fillCapacity').addEventListener('click',()=>{$('trainCount').value=String(capacity(building,Number($('buildingLevel').value)));calculate();});$('decreaseCount').addEventListener('click',()=>{$('trainCount').value=String(Math.max(1,(currentQuote?.count||1)-1));calculate();});$('increaseCount').addEventListener('click',()=>{$('trainCount').value=String(Math.min(1000000,(currentQuote?.count||0)+1));calculate();});
$('cavalryExample').addEventListener('click',()=>{applyInput({building:'stable',unitId:'LightCavalry',count:100,forge:0,buildingLevel:3,castleLevel:3,heroPalaceLevel:3});toast('فارس العرب: قصر الأبطال ٣، ومبنى تدريب ٣');});$('forgeExample').addEventListener('click',()=>{$('forgeLevel').value=Number($('forgeLevel').value)===3?'20':'3';calculate();});$('levelsAxis').addEventListener('change',renderLevels);$('unitDetails').addEventListener('click',showDetails);$('selectedUnitArt').addEventListener('click',showDetails);$('quotePanel').addEventListener('click',e=>{if(e.target.closest('[data-open-unit]'))showDetails();});$('buildingDetails').addEventListener('click',showBuildingDetails);
$('openTraining').addEventListener('click',()=>{setSectionActive('training');$('setupTitle').scrollIntoView({behavior:'smooth',block:'start'});});$('openForge').addEventListener('click',showForge);
$('forgeUnitSelect').innerHTML=Object.entries(BUILDING_CONFIG).map(([id,c])=>`<optgroup label="${esc(c.name)}">${c.unitIds.map(unitId=>`<option value="${unitId}">${esc(unitMap[unitId].name)}</option>`).join('')}</optgroup>`).join('');$('forgeDetailLevel').innerHTML=$('forgeLevel').innerHTML;
for(const id of ['forgeUnitSelect','forgeDetailLevel'])$(id).addEventListener('change',renderForgeDetails);$('applyForge').addEventListener('click',()=>{const q=forgePreview();applyInput({...stateByBuilding[q.building],building:q.building,unitId:q.unitId,forge:q.forge});$('forgeDialog').close();$('forgeLevel').scrollIntoView({behavior:'smooth',block:'center'});toast('طُبق الجندي ومستوى الحداد على التدريب');});$('forgeDialog').addEventListener('close',()=>setSectionActive('training'));
$('shareForge').addEventListener('click',()=>{const q=forgePreview(),input={...stateByBuilding[q.building],building:q.building,unitId:q.unitId,forge:q.forge};exposeShare(location.origin+location.pathname+'#f='+encodeTraining(input),'forgeShareOutput');});
$('wallLevel').innerHTML='<option value="0">٠ — بدون سور</option>'+Array.from({length:30},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');$('wallLevel').value='10';$('wallDefenderUnit').innerHTML=$('forgeUnitSelect').innerHTML;for(const id of ['wallDefenderForge','wallRamForge','wallCatapultForge'])$(id).innerHTML=$('forgeLevel').innerHTML;
$('openWall').addEventListener('click',showWall);$('wallDialog').addEventListener('close',()=>setSectionActive('training'));$('wallLevel').addEventListener('change',()=>{$('wallHp').value=String(Number($('wallLevel').value)*1000);calculateWall();});for(const[key,id]of Object.entries(wallFieldMap)){if(key==='level')continue;$(id).addEventListener($(id).tagName==='SELECT'?'change':'input',calculateWall);}$('wallAttackerWon').addEventListener('change',calculateWall);$('calculateWall').addEventListener('click',()=>{if(calculateWall())toast('حُسب أثر السور وفق مدخلاتك');});
$('useTrainingDefender').addEventListener('click',()=>{if(!currentQuote){$('wallError').textContent='صحّح حسبة التدريب أولًا لاستيراد المدافع.';$('wallError').hidden=false;return;}$('wallDefenderUnit').value=currentQuote.unitId;$('wallDefenderCount').value=String(currentQuote.count);$('wallDefenderForge').value=String(currentQuote.forge);calculateWall();});
$('shareWall').addEventListener('click',()=>{if(currentWallQuote)exposeShare(location.origin+location.pathname+'#w='+encodeWall(currentWallQuote.input),'wallShareOutput');});$('downloadWall').addEventListener('click',()=>{if(!currentWallQuote)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:TRAINING_VERSION,generatedAt:new Date().toISOString(),quote:currentWallQuote},null,2)],{type:'application/json'}));a.download='GloryKings_Wall_Conditional_Quote.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>$(el.dataset.close).close()));for(const id of ['unitDialog','buildingDialog','forgeDialog','wallDialog'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('shareTraining').addEventListener('click',async()=>{if(!currentInput)return;const url=location.origin+location.pathname+'#t='+encodeTraining(currentInput);$('shareOutput').value=url;$('shareOutput').hidden=false;try{await navigator.clipboard.writeText(url);toast('نُسخ رابط الحسبة');}catch{$('shareOutput').focus();$('shareOutput').select();toast('الرابط جاهز للنسخ');}});
$('downloadQuote').addEventListener('click',()=>{if(!currentQuote)return;const body={version:TRAINING_VERSION,generatedAt:new Date().toISOString(),input:currentInput,quote:currentQuote,buildingLevels:levelRows({...currentInput,axis:'building'}),forgeLevels:levelRows({...currentInput,axis:'forge'})};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(body,null,2)],{type:'application/json'}));a.download='GloryKings_Training_Approved_Quote.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
function loadHash(){const kind=location.hash.slice(1,3);if(!['t=','f=','w='].includes(kind))return false;try{for(const id of ['forgeDialog','wallDialog'])if($(id).open)$(id).close();if(kind==='w='){const input=decodeWall(location.hash.slice(3));renderBuilding();applyWallInput(input);showWall();}else{applyInput(decodeTraining(location.hash.slice(3)));if(kind==='f=')showForge();}return true;}catch(e){renderBuilding();$('trainingError').textContent=e.message+' تم فتح المثال الافتراضي.';$('trainingError').hidden=false;return true;}}
if(!loadHash())renderBuilding();window.addEventListener('hashchange',loadHash);
